class Quantity {
public:
    Quantity(double amount, std::string unit) : amount_(amount), unit_(std::move(unit)) {}
    double amount() const { return amount_; }
    const std::string& unit() const { return unit_; }
    friend bool operator==(const Quantity& a, const Quantity& b) {
        return std::tie(a.amount_, a.unit_) == std::tie(b.amount_, b.unit_);
    }
private:
    double amount_;
    std::string unit_;
};

